'use client';

import { ExpandableSearch } from '@/registry/ndeko/components/navbar/_parts/expandable-search';
import { LogoLink } from '@/registry/ndeko/components/navbar/_parts/logo';
import {
  MobileNav,
  MobileNavLinks,
} from '@/registry/ndeko/components/navbar/_parts/mobile-nav';
import {
  NavLinks,
  type NavLinkItem,
} from '@/registry/ndeko/components/navbar/_parts/nav-links';
import { useActiveLink } from '@/registry/ndeko/components/navbar/_parts/use-active-link';
import { HouseIcon, InboxIcon, ZapIcon } from '@/registry/ndeko/lib/icons';

const LINKS: NavLinkItem[] = [
  { href: '#', label: 'Home', icon: HouseIcon },
  { href: '#', label: 'Inbox', icon: InboxIcon },
  { href: '#', label: 'Insights', icon: ZapIcon },
];

export default function Navbar11() {
  const { activeLabel, navigate } = useActiveLink('Home');

  return (
    <header className='hairline-b border-border px-4 md:px-6'>
      <div className='flex h-16 items-center justify-between gap-4'>
        <div className='flex flex-1 items-center gap-2'>
          <MobileNav className='w-40'>
            <MobileNavLinks
              links={LINKS}
              activeLabel={activeLabel}
              onNavigate={navigate}
              showsIcons
            />
          </MobileNav>
          <LogoLink />
        </div>
        <NavLinks
          links={LINKS}
          activeLabel={activeLabel}
          onNavigate={navigate}
          display='icon-label'
          className='max-md:hidden'
        />
        <div className='flex flex-1 items-center justify-end gap-2'>
          <ExpandableSearch />
        </div>
      </div>
    </header>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { SearchIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };
const EXIT_TRANSITION: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT_TRANSITION },
};

const SURFACE = [
  'm-0 rounded-md transition-[box-shadow,background-color] duration-150 ease-(--ease-out-strong)',
  'has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-offset-2 has-focus-visible:ring-offset-background',
].join(' ');

const OPEN_SURFACE = [
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.05)] hairline-ring ring-foreground/12 dark:bg-foreground/[0.04] dark:ring-foreground/15',
  'has-focus-visible:ring-[3px] has-focus-visible:ring-ring/25 has-focus-visible:ring-offset-0',
].join(' ');

const INPUT =
  'h-full min-w-0 flex-1 bg-transparent text-base text-foreground outline-none placeholder:text-muted-foreground/75 md:text-[13px] [&::-webkit-search-cancel-button]:appearance-none';

function surfaceClassOf(isOpen: boolean) {
  if (isOpen) {
    return cn(SURFACE, OPEN_SURFACE);
  }
  return SURFACE;
}

type ExpandableSearchProps = {
  className?: string;
  fieldClassName?: string;
};

function ExpandableSearch({
  className,
  fieldClassName,
}: ExpandableSearchProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const shouldRestoreFocus = useRef(false);
  const isClosed = !isOpen;

  useEffect(() => {
    if (isOpen) {
      inputRef.current?.focus();
      return;
    }
    if (shouldRestoreFocus.current) {
      shouldRestoreFocus.current = false;
      buttonRef.current?.focus();
    }
  }, [isOpen]);

  function openSearch() {
    setIsOpen(true);
  }

  function updateQuery(event: React.ChangeEvent<HTMLInputElement>) {
    setQuery(event.target.value);
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    shouldRestoreFocus.current = true;
    setQuery('');
    setIsOpen(false);
  }

  function closeWhenEmpty() {
    const isEmpty = query.trim() === '';
    if (isEmpty) {
      setIsOpen(false);
    }
  }

  return (
    <AnimatedSize
      axis='width'
      role='search'
      className={cn(surfaceClassOf(isOpen), className)}
      contentClassName='relative flex p-0'
    >
      <AnimatePresence mode='popLayout' initial={false}>
        {isClosed && (
          <motion.div
            key='closed'
            className='flex'
            variants={FADE_VARIANTS}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            <Button
              ref={buttonRef}
              variant='ghost'
              size='icon'
              aria-label='Open search'
              onClick={openSearch}
              className='text-muted-foreground focus-visible:ring-0 focus-visible:ring-offset-0'
            >
              <SearchIcon />
            </Button>
          </motion.div>
        )}
        {isOpen && (
          <motion.div
            key='open'
            className={cn(
              'flex h-8 w-56 items-center gap-2 ps-2 pe-2.5',
              fieldClassName
            )}
            variants={FADE_VARIANTS}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            <SearchIcon className='text-muted-foreground/80 size-4 shrink-0' />
            <input
              ref={inputRef}
              type='search'
              value={query}
              onChange={updateQuery}
              onKeyDown={closeOnEscape}
              onBlur={closeWhenEmpty}
              placeholder='Search…'
              aria-label='Search'
              className={INPUT}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </AnimatedSize>
  );
}

export { ExpandableSearch };

import { cn } from '@/registry/ndeko/lib/utils';

function Logo({ className }: { className?: string }) {
  return (
    <svg
      viewBox='0 0 32 32'
      fill='none'
      aria-hidden='true'
      className={cn('size-8', className)}
    >
      <rect width='32' height='32' rx='9' fill='currentColor' />
      <circle
        cx='16'
        cy='16'
        r='6.25'
        strokeWidth='2.5'
        className='stroke-background'
      />
      <circle cx='16' cy='16' r='1.75' className='fill-background' />
    </svg>
  );
}

function LogoLink({ className }: { className?: string }) {
  return (
    <a
      href='#'
      aria-label='Home'
      className={cn(
        'text-foreground focus-visible:ring-ring/25 flex shrink-0 rounded-[9px] outline-none focus-visible:ring-[3px]',
        className
      )}
    >
      <Logo />
    </a>
  );
}

export { Logo, LogoLink };

'use client';

import { createContext, useContext, useState } from 'react';

import {
  isPlaceholderHref,
  NavLinkIcon,
  type NavLinkItem,
} from '@/registry/ndeko/components/navbar/_parts/nav-links';
import {
  MENU_ITEM,
  MENU_LABEL,
  MENU_SEPARATOR,
} from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

const CloseMenuContext = createContext<() => void>(() => undefined);

const BAR =
  'origin-center transition-[translate,rotate] duration-300 ease-(--ease-out-strong)';

const LINK_ROW = cn(
  MENU_ITEM,
  'text-muted-foreground cursor-pointer transition-colors duration-150',
  'hover:bg-foreground/5 hover:text-foreground focus-visible:bg-foreground/5 focus-visible:text-foreground',
  'data-active:bg-foreground/[0.06] data-active:text-foreground dark:data-active:bg-foreground/10'
);

function menuLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Close menu';
  }
  return 'Open menu';
}

function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

function MenuToggleIcon() {
  return (
    <svg
      viewBox='0 0 24 24'
      fill='none'
      stroke='currentColor'
      strokeWidth='1.75'
      strokeLinecap='round'
      strokeLinejoin='round'
      aria-hidden='true'
      className='pointer-events-none size-4'
    >
      <path
        d='M4 12H20'
        className={cn(
          BAR,
          '-translate-y-[7px] group-aria-expanded/button:translate-y-0 group-aria-expanded/button:rotate-[315deg]'
        )}
      />
      <path
        d='M4 12H20'
        className={cn(BAR, 'group-aria-expanded/button:rotate-45')}
      />
      <path
        d='M4 12H20'
        className={cn(
          BAR,
          'translate-y-[7px] group-aria-expanded/button:translate-y-0 group-aria-expanded/button:rotate-[135deg]'
        )}
      />
    </svg>
  );
}

type MobileNavProps = {
  children: React.ReactNode;
  className?: string;
};

function MobileNav({ children, className }: MobileNavProps) {
  const [isOpen, setIsOpen] = useState(false);

  function changeOpen(open: boolean) {
    setIsOpen(open);
  }

  function closeMenu() {
    setIsOpen(false);
  }

  return (
    <Popover open={isOpen} onOpenChange={changeOpen}>
      <PopoverTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            aria-label={menuLabelOf(isOpen)}
            className='md:hidden'
          />
        }
      >
        <MenuToggleIcon />
      </PopoverTrigger>
      <PopoverContent
        align='start'
        className={cn('w-44 p-1 md:hidden', className)}
      >
        <nav aria-label='Main'>
          <CloseMenuContext.Provider value={closeMenu}>
            {children}
          </CloseMenuContext.Provider>
        </nav>
      </PopoverContent>
    </Popover>
  );
}

type MobileNavLinkProps = {
  href: string;
  isActive?: boolean;
  onClick?: () => void;
  className?: string;
  children: React.ReactNode;
};

function MobileNavLink({
  href,
  isActive = false,
  onClick,
  className,
  children,
}: MobileNavLinkProps) {
  const closeMenu = useContext(CloseMenuContext);

  function follow(event: React.MouseEvent<HTMLAnchorElement>) {
    if (isPlaceholderHref(href)) {
      event.preventDefault();
    }
    onClick?.();
    closeMenu();
  }

  return (
    <a
      href={href}
      aria-current={ariaCurrentOf(isActive)}
      data-active={isActive || undefined}
      onClick={follow}
      className={cn(LINK_ROW, className)}
    >
      {children}
    </a>
  );
}

type MobileNavLinksProps = {
  links: NavLinkItem[];
  activeLabel?: string;
  onNavigate?: (label: string) => void;
  showsIcons?: boolean;
};

function MobileNavLinks({
  links,
  activeLabel,
  onNavigate,
  showsIcons = false,
}: MobileNavLinksProps) {
  return (
    <ul className='flex flex-col'>
      {links.map((link) => (
        <li key={link.label}>
          <MobileNavLink
            href={link.href}
            isActive={link.label === activeLabel}
            onClick={() => onNavigate?.(link.label)}
          >
            {showsIcons && <NavLinkIcon icon={link.icon} />}
            {link.label}
          </MobileNavLink>
        </li>
      ))}
    </ul>
  );
}

function MobileNavHeading({ children }: { children: React.ReactNode }) {
  return <div className={MENU_LABEL}>{children}</div>;
}

function MobileNavSeparator() {
  return (
    <div
      role='separator'
      aria-orientation='horizontal'
      className={MENU_SEPARATOR}
    />
  );
}

export {
  MobileNav,
  MobileNavHeading,
  MobileNavLink,
  MobileNavLinks,
  MobileNavSeparator,
};

'use client';

import {
  LayoutGroup,
  motion,
  type Transition,
  useReducedMotion,
} from 'motion/react';
import { useId } from 'react';

import type { Icon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  NavigationMenu,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
} from '@/registry/ndeko/ui/navigation-menu';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

type NavLinkItem = { label: string; href: string; icon?: Icon };

type NavIndicator = 'pill' | 'underline';

type NavLinkDisplay = 'label' | 'icon-label' | 'icon';

const SLIDE_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};
const INSTANT_TRANSITION: Transition = { duration: 0 };

const LINK_BASE =
  'relative flex-row items-center gap-2 py-0 font-medium text-muted-foreground hover:bg-transparent hover:text-foreground data-active:bg-transparent data-active:text-foreground';

const LINK_SHAPE: Record<NavIndicator, string> = {
  pill: 'h-8 rounded-md px-3',
  underline: 'h-full rounded-sm px-0.5',
};

const ICON_ONLY_SHAPE = 'size-8 justify-center px-0';

const LIST_CLASS: Record<NavIndicator, string> = {
  pill: 'gap-1',
  underline: 'h-full gap-6',
};

const ITEM_CLASS: Record<NavIndicator, string> = {
  pill: '',
  underline: 'h-full',
};

const INDICATOR_CLASS: Record<NavIndicator, string> = {
  pill: 'absolute inset-0 rounded-md bg-foreground/[0.06] dark:bg-foreground/10',
  underline: 'absolute inset-x-0 bottom-0 h-0.5 rounded-full bg-primary',
};

function slideTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT_TRANSITION;
  }
  return SLIDE_TRANSITION;
}

function isPlaceholderHref(href: string) {
  return href === '#';
}

function NavLinkIcon({ icon: LinkIcon }: { icon?: Icon }) {
  if (!LinkIcon) {
    return null;
  }
  return <LinkIcon className='size-4' />;
}

type NavLinksItemProps = {
  link: NavLinkItem;
  isActive: boolean;
  indicator: NavIndicator;
  display: NavLinkDisplay;
  transition: Transition;
  onFollow: (
    event: React.MouseEvent<HTMLAnchorElement>,
    link: NavLinkItem
  ) => void;
};

function NavLinksItem({
  link,
  isActive,
  indicator,
  display,
  transition,
  onFollow,
}: NavLinksItemProps) {
  const isIconOnly = display === 'icon';
  const showsIcon = display !== 'label';
  const linkClassName = cn(
    LINK_BASE,
    LINK_SHAPE[indicator],
    isIconOnly && ICON_ONLY_SHAPE
  );

  function follow(event: React.MouseEvent<HTMLAnchorElement>) {
    onFollow(event, link);
  }

  const content = (
    <>
      {isActive && (
        <motion.span
          layoutId='active-link-indicator'
          transition={transition}
          className={INDICATOR_CLASS[indicator]}
        />
      )}
      <span className='relative flex items-center gap-2'>
        {showsIcon && <NavLinkIcon icon={link.icon} />}
        {isIconOnly && <span className='sr-only'>{link.label}</span>}
        {!isIconOnly && link.label}
      </span>
    </>
  );

  if (isIconOnly) {
    return (
      <NavigationMenuItem className={ITEM_CLASS[indicator]}>
        <Tooltip>
          <TooltipTrigger
            render={
              <NavigationMenuLink
                href={link.href}
                active={isActive}
                onClick={follow}
                className={linkClassName}
              />
            }
          >
            {content}
          </TooltipTrigger>
          <TooltipContent side='bottom'>{link.label}</TooltipContent>
        </Tooltip>
      </NavigationMenuItem>
    );
  }

  return (
    <NavigationMenuItem className={ITEM_CLASS[indicator]}>
      <NavigationMenuLink
        href={link.href}
        active={isActive}
        onClick={follow}
        className={linkClassName}
      >
        {content}
      </NavigationMenuLink>
    </NavigationMenuItem>
  );
}

type NavLinksProps = {
  links: NavLinkItem[];
  activeLabel?: string;
  onNavigate: (label: string) => void;
  indicator?: NavIndicator;
  display?: NavLinkDisplay;
  className?: string;
};

function NavLinks({
  links,
  activeLabel,
  onNavigate,
  indicator = 'pill',
  display = 'label',
  className,
}: NavLinksProps) {
  const groupId = useId();
  const shouldReduceMotion = useReducedMotion();
  const transition = slideTransitionOf(shouldReduceMotion);
  const isUnderline = indicator === 'underline';

  function followLink(
    event: React.MouseEvent<HTMLAnchorElement>,
    link: NavLinkItem
  ) {
    if (isPlaceholderHref(link.href)) {
      event.preventDefault();
    }
    onNavigate(link.label);
  }

  return (
    <LayoutGroup id={groupId}>
      <TooltipProvider>
        <NavigationMenu
          aria-label='Main'
          className={cn(isUnderline && 'h-full', className)}
        >
          <NavigationMenuList className={LIST_CLASS[indicator]}>
            {links.map((link) => (
              <NavLinksItem
                key={link.label}
                link={link}
                isActive={link.label === activeLabel}
                indicator={indicator}
                display={display}
                transition={transition}
                onFollow={followLink}
              />
            ))}
          </NavigationMenuList>
        </NavigationMenu>
      </TooltipProvider>
    </LayoutGroup>
  );
}

export {
  NavLinkIcon,
  NavLinks,
  isPlaceholderHref,
  type NavIndicator,
  type NavLinkDisplay,
  type NavLinkItem,
};

import { useState } from 'react';

function useActiveLink(initialLabel?: string) {
  const [activeLabel, setActiveLabel] = useState(initialLabel);

  function navigate(label: string) {
    setActiveLabel(label);
  }

  return { activeLabel, navigate };
}

export { useActiveLink };
